from durable.lang import ruleset, when_all, assert_fact

with ruleset('order'):
    @when_all(m.units > 100)
    def volume_discount(c):
        c.assert_fact({'subject': c.m.subject, 'discount': 0.10})

    @when_all((m.discount > 0) & (m.approved == True))
    def free_shipping(c):
        c.assert_fact({'subject': c.m.subject, 'free_shipping': True})

assert_fact('order', {'subject': 'A-1', 'units': 250, 'approved': True})
